.ds-nav{display:flex;align-items:center;gap:30px;min-height:80px;background:var(--page-background);border-bottom:1px solid var(--line);font-family:var(--font-manrope),sans-serif;font-size:13px;font-weight:500;color:var(--foreground)}.ds-nav > a{padding-block:12px;color:inherit;text-decoration:none;transition:color 160ms ease}.ds-nav > a:hover{color:var(--accent);text-decoration:underline;text-underline-offset:.5em}.ds-component:focus-visible{outline:2px solid var(--accent);outline-offset:5px} .ds-language-picker{font-family:var(--font-manrope),sans-serif}.ds-language-picker p{margin:0}.ds-language-option{color:inherit;text-decoration:none}.ds-language-trigger:focus-visible,.ds-language-option:focus-visible{outline:2px solid var(--accent);outline-offset:5px} .ds-language-picker { position:relative; }
.ds-language-trigger { display:flex; align-items:center; justify-content:center; gap:8px; min-height:44px; padding:10px 14px; border:1px solid var(--line); border-radius:24px; color:var(--foreground); background:transparent; cursor:pointer; list-style:none; font-size:12px; font-weight:500; user-select:none; transition:background-color 160ms ease,border-color 160ms ease,transform 140ms var(--ease-out); }
.ds-language-trigger::-webkit-details-marker { display:none; }
.ds-language-trigger svg { flex-shrink:0; }
.ds-language-trigger:active { transform:scale(.97); }
.ds-language-trigger__code { display:none; }
.ds-language-trigger__caret { color:var(--muted); transition:transform 180ms var(--ease-out); }
.ds-language-picker[open] .ds-language-trigger__caret { transform:rotate(180deg); }
.ds-language-picker[open] .ds-language-trigger { background:var(--surface); border-color:var(--accent); }
.ds-language-panel { position:absolute; z-index:30; right:0; top:calc(100% + 12px); width:256px; padding:12px; background:var(--background); border:1px solid var(--line); border-radius:12px; box-shadow:0 12px 32px rgba(22,19,41,.14); transform-origin:top right; animation:language-enter 180ms var(--ease-out); }
.ds-language-picker:not([open]) .ds-language-panel { display:none; }
.ds-language-panel__title { padding:4px 10px 12px; color:var(--foreground); font-size:13px; font-weight:600; line-height:1.5; }
.ds-language-options { display:grid; gap:4px; }
.ds-language-option { display:flex; align-items:center; justify-content:space-between; gap:16px; min-height:64px; padding:12px; border-radius:8px; transition:background-color 160ms ease; }
.ds-language-option__text { display:grid; gap:3px; }
.ds-language-option__name { color:var(--foreground); font-size:14px; font-weight:500; line-height:1.4; }
.ds-language-option__description { color:var(--muted); font-size:11px; line-height:1.4; }
.ds-language-option__mark { display:grid; place-items:center; width:24px; color:var(--muted); font-size:10px; font-weight:600; }
.ds-language-option[aria-checked='true'] { background:color-mix(in srgb,var(--background) 90%,var(--accent) 10%); }
.ds-language-option[aria-checked='true'] .ds-language-option__mark { color:var(--accent); }
.ds-language-option:focus-visible { outline-offset:-2px; }
.ds-language-panel__note { margin-top:12px; padding:12px 10px 3px; border-top:1px solid var(--line); font-size:11px; line-height:1.5; }
@keyframes language-enter { from { opacity:0; transform:translateY(-5px) scale(.98); } to { opacity:1; transform:translateY(0) scale(1); } }
@media (hover:hover) and (pointer:fine) { .ds-language-trigger:hover { background:var(--surface); border-color:var(--foreground); } .ds-language-option:hover { background:var(--surface); } }
@media (max-width:700px) {
 .ds-language-trigger { gap:6px; padding:10px; }
 .ds-language-trigger__name { display:none; }
 .ds-language-trigger__code { display:block; font-size:11px; }
 .ds-language-panel { position:fixed; top:86px; left:20px; right:20px; width:auto; transform-origin:top center; }
}

.ds-language-picker[data-keyboard='true'] .ds-language-panel { animation:none; }
.ds-language-picker[data-keyboard='true'] .ds-language-trigger__caret { transition:none; }
@media(prefers-reduced-motion:reduce){.ds-language-panel{animation:none}.ds-language-trigger,.ds-language-trigger__caret,.ds-language-option{transition:none}}.ds-nav>.ds-language-picker{margin-left:auto}@media(max-width:1100px){.ds-nav{gap:18px}}@media(max-width:700px){.ds-nav{gap:10px}}

